draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw person
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 80);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 - 30, H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 + 30, H/2 + 60);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 - 20, H/2 + 120);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 + 20, H/2 + 120);
  ctx.stroke();

  // fear
  ctx.fillStyle = 'gray';
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();

  // brave expression
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 20, 10, 0, Math.PI);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 10);
  ctx.lineTo(W/2 + 15, H/2 - 10);
  ctx.stroke();

  ctx.restore();
}
